    }

    @Test
    void motoboyAcimaDoPesoRetornaModalidadeIndisponivel() throws Exception {
        String corpo = """
                {
                  "itens": [
                    { "nome": "Halteres", "precoUnitario": 199.90, "quantidade": 3, "pesoKg": 2.5 }
